css:
.d-dw{position:relative;box-sizing:border-box;width:300px;max-width:100%;height:150px;perspective:700px;perspective-origin:50% 40%}
.d-dw-under{position:absolute;inset:0;display:flex;align-items:flex-start;padding:10px 16px;box-sizing:border-box;border:1px solid var(--line);border-radius:10px;background:var(--bg);color:var(--muted);font-size:11px}
.d-dw-page{position:absolute;inset:0;display:flex;flex-direction:column;justify-content:center;gap:2px;padding:12px 16px;box-sizing:border-box;border:1px solid var(--line);border-radius:10px;background:var(--paper);box-shadow:inset 0 1px 0 #fff5;transform-style:preserve-3d;transition:transform 280ms cubic-bezier(.34,1.56,.64,1)}
.d-dw-on .d-dw-page{transform:translateZ(58px) translateY(-20px) rotateX(6deg)}
.d-dw-k{font-family:var(--font-mono);font-size:11px;letter-spacing:.08em;color:var(--faint)}
.d-dw-v{font-size:21px;font-weight:650;letter-spacing:-.01em;color:var(--ink)}
.d-dw-n{font-size:11px;color:var(--muted)}
.d-dw-handle{position:absolute;left:50%;bottom:-1px;z-index:2;height:22px;padding:0 12px;border:1px solid var(--line);border-radius:999px;background:var(--paper);color:var(--muted);font:inherit;font-size:11px;cursor:pointer;transform:translateX(-50%);-webkit-tap-highlight-color:transparent}
.d-dw-on .d-dw-handle{color:var(--ink);border-color:var(--ink)}
.d-dw-handle:focus-visible{outline:1px solid var(--ink);outline-offset:2px}

init:
root => {
  const box = root.querySelector('.d-dw');
  if (!box) return;
  const btn = box.querySelector('.d-dw-handle');
  if (!btn) return;
  btn.onclick = () => {
    const on = !box.classList.contains('d-dw-on');
    box.classList.toggle('d-dw-on', on);
    btn.setAttribute('aria-expanded', on ? 'true' : 'false');
    btn.textContent = on ? '推回' : '拉出';
  };
}
